/* Gulczinski Adrenal Disease 2026, Parts I and II. Sixteen supplied objectives.
 * Brief labeled corrections distinguish lecture simplifications from safe clinical interpretation.
 */
(function(){
  "use strict";
  function q(prompt,answer,wrong,explanation){return {prompt:prompt,choices:[answer].concat(wrong),correct:0,explanation:explanation};}
  function u(title,html,coverage,test,apply){return {title:title,html:html,coverage:coverage,test:test,apply:apply};}
  function s(id,title,description,units){
    var result={id:id,title:title,description:description,cards:[],test:[],apply:[]};
    units.forEach(function(unit,index){result.cards.push({title:unit.title,html:unit.html,coverage:unit.coverage});["test","apply"].forEach(function(mode){unit[mode].forEach(function(question){question.card=index;result[mode].push(question);});});});
    return result;
  }
  function ref(url,label){return '<a href="'+url+'" target="_blank" rel="noopener noreferrer">'+label+'</a>';}
  var pai=ref('https://www.endocrine.org/clinical-practice-guidelines/primary-adrenal-insufficiency','Endocrine Society: adrenal insufficiency');
  var crisis=ref('https://www.endocrinology.org/adrenal-crisis','Society for Endocrinology: crisis care');
  var steroid=ref('https://www.endocrine.org/clinical-practice-guidelines/glucocorticoid-induced-adrenal-insufficiency','ESE/Endocrine Society: steroid-related insufficiency');
  var cushing=ref('https://www.endocrine.org/clinical-practice-guidelines/diagnosis-of-cushing-syndrome','Endocrine Society: Cushing testing');
  var aldo=ref('https://www.endocrine.org/clinical-practice-guidelines/primary-aldosteronism-2','Endocrine Society: primary aldosteronism');
  var ppgl=ref('https://academic.oup.com/jcem/article/99/6/1915/2537399','Endocrine Society: pheochromocytoma/paraganglioma');
  var incidental=ref('https://www.ese-hormones.org/media/jjwm0ip2/adrenal-incidentaloma-guideline-presentation-ece-2023.pdf','ESE: adrenal incidentalomas');
  window.ADRENAL_DISEASE_OBJECTIVES=[
    s('01-anatomy-axes','1. Adrenal anatomy, physiology, HPA, and RAAS','Objective 1. Part I slides 2–9; Part II slides 2–4.',[
      u('Cortex layers and medulla','<p>Adrenals sit above the kidneys. The <strong>cortex</strong> has three steroid-producing layers, outside inward: <strong>glomerulosa → aldosterone</strong>, <strong>fasciculata → cortisol</strong>, <strong>reticularis → adrenal androgens</strong>.</p><p>The separate-function <strong>medulla</strong> contains chromaffin cells producing <strong>epinephrine and norepinephrine</strong>. Remember outer-to-inner cortex as salt, sugar, sex.</p>',['adrenal-location','glomerulosa-aldosterone','fasciculata-cortisol','reticularis-androgens','medulla-catecholamines'],[
        q('Which cortex layer produces aldosterone?','Zona glomerulosa',['Zona fasciculata','Zona reticularis','Adrenal medulla'],'The outer cortex produces the mineralocorticoid aldosterone.'),
        q('Which cortex layer produces cortisol?','Zona fasciculata',['Zona glomerulosa','Zona reticularis','Adrenal medulla'],'The middle cortex produces glucocorticoids.'),
        q('Which cortex layer produces adrenal androgens?','Zona reticularis',['Zona glomerulosa','Adrenal medulla','Zona fasciculata'],'The inner cortex produces adrenal androgens.')
      ],[q('A tumor of chromaffin cells within an adrenal gland secretes epinephrine and norepinephrine. Where does it arise?','Adrenal medulla',['Aldosterone-producing outer cortex','Cortisol-producing middle cortex','Androgen-producing inner cortex'],'Chromaffin cells belong to the catecholamine-producing medulla.')]),
      u('HPA feedback and the cortisol rhythm','<p><strong>Hypothalamic CRH → anterior pituitary ACTH → adrenal cortisol</strong>. Cortisol feeds back to suppress CRH/ACTH. Stress increases the demand for cortisol.</p><p>Cortisol normally peaks around waking/early morning and falls toward late night. ACTH primarily regulates cortisol; RAAS and potassium are the major aldosterone regulators.</p>',['crh-acth-cortisol','cortisol-feedback','cortisol-rhythm','cortisol-versus-aldo-control'],[
        q('What is the correct HPA sequence?','CRH from hypothalamus → ACTH from anterior pituitary → adrenal cortisol',['ACTH from adrenal → CRH from pituitary → hypothalamic cortisol','Renin → ACTH → thyroid cortisol','Cortisol → aldosterone → CRH as the forward pathway'],'Know the source of each signal as well as its order.'),
        q('What does rising cortisol normally do to CRH and ACTH?','Suppresses both through negative feedback',['Raises both indefinitely','Suppresses renin but never affects the HPA axis','Converts ACTH directly into aldosterone'],'Feedback explains hormone patterns in adrenal and central disease.')
      ],[q('A normal daytime sleeper is being evaluated using a late-night cortisol test. Why must the clinician consider the sleep schedule?','Cortisol follows a circadian rhythm, so usual timing assumptions may not fit',['Cortisol has no normal daily variation','ACTH controls only renal blood flow','All cortisol measurements are interchangeable'],'Timing matters because cortisol is normally low late at night in a typical sleep schedule.')]),
      u('What cortisol and adrenal androgens do','<p>Cortisol maintains vascular tone/cardiac output and stress fuel: more gluconeogenesis, fat/protein breakdown, and less glucose uptake in some tissues. It suppresses inflammation; excess inhibits tissue repair, growth/reproduction and promotes bone/connective-tissue loss.</p><p>Adrenal androgens contribute to female sexual well-being. Loss has much less clinical effect in men because testicular androgen production predominates.</p>',['cortisol-vascular','cortisol-metabolic','cortisol-immune-repair','cortisol-bone-growth','androgen-sex-difference'],[
        q('Which combination describes important cortisol effects?','Maintains vascular responsiveness and increases stress fuel while suppressing inflammation',['Promotes glucose uptake everywhere and blocks gluconeogenesis','Produces catecholamines directly in the cortex','Has only reproductive effects'],'These actions explain hypotension with deficiency and catabolic/metabolic effects with excess.'),
        q('Why does adrenal androgen loss usually cause fewer symptoms in men?','Testicular androgen production predominates',['Men lack androgen receptors','The adrenal medulla replaces all testosterone','Aldosterone is the main male androgen'],'The relative contribution of the adrenal glands differs by sex.')
      ],[q('A patient with sustained cortisol excess develops hyperglycemia, thin skin, and muscle wasting. Which actions connect these findings?','Increased glucose production and protein catabolism with inhibited tissue repair',['Reduced glucose production with increased protein synthesis','Isolated aldosterone deficiency','Reduced catecholamine synthesis alone'],'The clinical findings follow cortisol’s metabolic and catabolic actions.')]),
      u('RAAS restores perfusion; aldosterone retains salt','<p>Low renal perfusion stimulates <strong>kidney renin</strong>. Renin converts liver angiotensinogen to angiotensin I; <strong>ACE</strong> converts I to II. Angiotensin II constricts vessels and stimulates adrenal aldosterone.</p><p>Aldosterone promotes distal renal <strong>Na/water retention and K/H excretion</strong>, supporting BP/volume and suppressing renin as perfusion improves.</p><p><strong>Clarification:</strong> elevated K directly stimulates aldosterone, rather than being the main stimulus for renin. '+ref('https://www.ncbi.nlm.nih.gov/books/NBK279079/','Aldosterone regulation reference')+'</p>',['renin-kidney-perfusion','angiotensinogen-liver','ace-angII','angII-vasoconstriction-aldo','aldo-na-water-k-h','raas-feedback','k-direct-aldo'],[
        q('Which sequence describes the renin-angiotensin pathway?','Renin acts on angiotensinogen → angiotensin I → ACE → angiotensin II',['ACTH converts cortisol to angiotensin II','ACE converts aldosterone directly to renin','Renin is secreted by the thyroid and makes cortisol'],'The kidney, liver substrate, and ACE connect reduced perfusion to angiotensin II.'),
        q('Which renal effect is caused by aldosterone?','Retains Na/water and increases K/H excretion',['Excretes Na while retaining K and H','Retains only glucose without changing electrolytes','Stops all distal sodium transport'],'Deficiency and excess produce opposite potassium/acid-base patterns.')
      ],[q('A fall in renal perfusion raises renin and angiotensin II. Which response helps restore circulating volume?','More aldosterone-mediated sodium/water retention',['Complete inhibition of aldosterone','More sodium wasting from the distal nephron','Cortisol conversion into renin'],'Water follows sodium, helping restore volume and reduce the renin stimulus.')])
    ]),
    s('02-primary-insufficiency','2. Primary adrenal insufficiency: causes and presentation','Objective 2. Part I slides 15–29, 33.',[
      u('Primary failure: low cortisol, often low aldosterone','<p>Primary insufficiency originates in the <strong>adrenal cortex</strong>. Destructive disease can reduce cortisol, aldosterone, and adrenal androgens. Loss of cortisol feedback raises <strong>ACTH</strong>; loss of aldosterone promotes salt/volume loss and K retention.</p><p>High ACTH-related melanocortin activity explains hyperpigmentation. Contrast this with low/inappropriately normal ACTH in central insufficiency.</p>',['primary-cortex','primary-cortisol-aldo-androgen','primary-high-acth','pigment-mechanism'],[
        q('Which cortisol/ACTH pattern supports primary adrenal insufficiency?','Low cortisol with high ACTH',['Low cortisol with low ACTH','High cortisol with suppressed ACTH','High cortisol with high aldosterone as the definition'],'The failing target gland cannot respond adequately to a strong pituitary signal.')
      ],[q('A patient has cortisol deficiency, hyperpigmented creases, salt craving, and hyperkalemia. Which site of dysfunction best explains the pattern?','Adrenal cortex',['Hypothalamus alone with preserved mineralocorticoids','Pituitary alone with low ACTH','Catecholamine-producing medulla alone'],'Both cortisol and mineralocorticoid loss point toward primary cortical failure.')]),
      u('Autoimmune Addison disease and polyglandular syndromes','<p><strong>Autoimmune adrenal destruction</strong> is the common primary cause in the US/industrialized settings. It may occur alone or with other autoimmune disorders.</p><p><strong>PGA type I:</strong> Addison disease, hypoparathyroidism, mucocutaneous candidiasis, often childhood.</p><p><strong>PGA type II:</strong> Addison disease with autoimmune thyroid disease and/or T1DM, generally later onset.</p>',['autoimmune-common-us','pga1-triad','pga2-associations'],[
        q('What is the most common primary adrenal-insufficiency cause in the US lecture?','Autoimmune adrenal destruction',['Tuberculosis in every region','Isolated medullary adenoma','Excess renin production'],'The geographic distinction matters: TB remains relevant where endemic.'),
        q('Which combination fits PGA type I?','Addison disease, hypoparathyroidism, and mucocutaneous candidiasis',['Addison disease, T1DM, and autoimmune thyroid disease','Pheochromocytoma and medullary thyroid cancer','Pituitary adenoma and insulinoma'],'Type I is the childhood-predominant triad.'),
        q('Which disorders commonly accompany Addison disease in PGA type II?','Autoimmune thyroid disease and/or T1DM',['Candidiasis and hypoparathyroidism as its defining triad','Only catecholamine-secreting tumors','Only nonautoimmune renal artery stenosis'],'Type II links adrenal, thyroid, and pancreatic autoimmunity.')
      ],[q('A patient with autoimmune thyroid disease and T1DM develops low cortisol, high ACTH, and salt wasting. Which association should you recognize?','PGA type II with autoimmune adrenal insufficiency',['PGA type I solely because diabetes is present','MEN2 as the cause of low cortisol','An isolated nonfunctioning pituitary mass with high cortisol'],'These autoimmune conditions can cluster.')]),
      u('Other primary causes: infection, injury, infiltration, congenital defects','<p><strong>Infection:</strong> TB, disseminated fungal infection such as histoplasmosis.</p><p><strong>Bilateral injury:</strong> hemorrhage/infarction with sepsis, anticoagulation, trauma or surgery. <strong>Infiltration:</strong> metastases, lymphoma, sarcoidosis.</p><p><strong>Iatrogenic:</strong> bilateral adrenalectomy or inhibition of steroid synthesis (e.g., ketoconazole, etomidate). <strong>Congenital adrenal hyperplasia:</strong> most commonly 21-hydroxylase deficiency; low cortisol can accompany salt-wasting crisis and androgen excess/virilization.</p>',['tb-fungal','hemorrhage-infarction','metastasis-lymphoma-sarcoid','adrenalectomy-drug','cah21-cortisol-androgens'],[
        q('Which history can directly cause primary cortical failure?','Bilateral adrenal hemorrhage or bilateral adrenalectomy',['Abrupt steroid withdrawal as isolated hypothalamic suppression','An isolated TSH deficiency','A unilateral small nonfunctioning cyst with a normal opposite gland'],'Both adrenals must be considered when evaluating destructive disease.'),
        q('How can 21-hydroxylase deficiency cause both insufficiency and virilization?','Reduced cortisol synthesis with precursors diverted toward androgen production',['Excess cortisol suppresses all androgen synthesis','The defect selectively makes excess aldosterone','Medullary catecholamines convert into cortisol'],'The blocked steroid pathway explains the two presentations.')
      ],[q('A neonate with virilization develops vomiting and hypotension from a salt-wasting crisis. Which lecture disorder connects these findings?','Congenital adrenal hyperplasia, commonly 21-hydroxylase deficiency',['Pituitary ACTH-secreting microadenoma','Adult hyporeninemic hypoaldosteronism','Uncomplicated primary aldosteronism'],'A congenital synthesis defect can affect cortisol, salt balance, and androgens.')]),
      u('Common insidious symptoms and examination findings','<p>Common: <strong>weakness/fatigue, hyperpigmentation, low BP/orthostasis and dehydration</strong>. Weight loss, poor appetite, nausea/vomiting, dizziness, muscle/joint aches, and <strong>salt craving</strong> also occur.</p><p>Pigment is conspicuous at creases, pressure areas, knuckles and new scars. Autoimmune disease can include vitiligo. Women may lose axillary/pubic hair from androgen deficiency.</p>',['primary-fatigue-weakness','primary-pigment-distribution','primary-orthostasis-volume','primary-weight-gi-salt','primary-vitiligo-hair'],[
        q('Which symptom cluster is typical of chronic primary adrenal insufficiency?','Fatigue, weight loss, orthostasis, salt craving, and hyperpigmentation',['Central weight gain, broad purple striae, and hypertension','Episodic hypertension with palpitations and sweating only','Persistent hypertension with hypokalemic alkalosis'],'The common cluster reflects cortisol and aldosterone deficiency.'),
        q('Where is Addison-associated hyperpigmentation often most visible?','Creases, pressure areas, knuckles, and new scars',['Only the cornea','Only old scars with all new scars spared','Only the abdomen as purple striae'],'ACTH-associated pigmentation has a recognizable distribution.')
      ],[q('A patient reports months of fatigue, poor appetite, weight loss, salt craving, and dizziness on standing. Creases are newly dark. Which diagnosis fits?','Primary adrenal insufficiency',['Cortisol excess','Primary aldosteronism','Pheochromocytoma as the sole explanation'],'The chronic clinical pattern deserves hormonal evaluation.')]),
      u('Laboratory pattern follows the missing hormones','<p><strong>Low Na, high K, and metabolic acidosis</strong> can accompany mineralocorticoid deficiency. Cortisol deficiency can cause <strong>hypoglycemia</strong>, especially in children/thin patients.</p><p>Volume depletion can raise renal-function markers. Primary disease: <strong>low cortisol, high ACTH; low aldosterone with high renin</strong> when salt-wasting mineralocorticoid deficiency is present.</p>',['primary-hypona-hyperk-acidosis','primary-hypoglycemia','primary-renal-volume','primary-renin-aldo'],[
        q('Which electrolyte/acid-base pattern supports mineralocorticoid deficiency?','Hyponatremia, hyperkalemia, and metabolic acidosis',['Hypernatremia, hypokalemia, and alkalosis in every case','Normal potassium with high aldosterone as proof of failure','Hypercalcemia alone with suppressed ACTH'],'Aldosterone loss reduces sodium conservation and K/H excretion.'),
        q('How do renin and aldosterone typically relate in salt-wasting primary adrenal failure?','High renin with low aldosterone',['Low renin with high aldosterone','Both high from autonomous aldosterone secretion','Both normal as a required diagnostic feature'],'The kidney requests salt retention, but the damaged adrenal cannot supply aldosterone.')
      ],[q('A fatigued hypotensive patient has Na 127, K 5.8, low cortisol, and high ACTH. How should the labs be interpreted?','Primary adrenal insufficiency with possible mineralocorticoid loss',['Central insufficiency is proven by the high ACTH','Cortisol excess is proven by the low Na','Primary aldosteronism is proven by the high K'],'The hormonal and electrolyte findings fit the same mechanism.')])
    ]),
    s('03-secondary-crisis','3. Secondary insufficiency and adrenal crisis: distinctions','Objective 3. Part I slides 11–12, 30–32, 45–47.',[
      u('Central insufficiency preserves aldosterone in most cases','<p><strong>Secondary:</strong> pituitary ACTH deficiency. <strong>Tertiary:</strong> deficient hypothalamic drive, often from chronic exogenous glucocorticoid suppression.</p><p>Low cortisol with low/inappropriately normal ACTH can cause fatigue, GI symptoms and hypotension. <strong>No ACTH-driven hyperpigmentation</strong>; aldosterone is generally preserved, so prominent salt craving, hyperkalemia and mineralocorticoid-related acidosis are usually absent. Hyponatremia can still occur.</p><p>Other pituitary hormone deficiencies may provide clues to secondary disease.</p>',['secondary-pituitary','tertiary-hypothalamic','central-low-acth','central-no-pigment','central-aldo-preserved','central-hypona-other-pituitary'],[
        q('Which feature most distinguishes central from primary adrenal insufficiency?','Low/inappropriately normal ACTH without hyperpigmentation and usually preserved aldosterone',['High ACTH with marked pigment in all cases','Autonomous aldosterone excess','Required hyperkalemia from complete aldosterone loss'],'Central cortisol deficiency does not usually remove RAAS-controlled aldosterone.'),
        q('Can hyponatremia occur in secondary adrenal insufficiency despite preserved aldosterone?','Yes; cortisol deficiency can still disturb water balance',['No; low sodium always proves primary disease','No; ACTH deficiency always causes hypernatremia','Only if cortisol is high'],'Do not use sodium alone to locate the defect.')
      ],[q('After pituitary surgery, a patient has low cortisol, low ACTH, normal K, no new pigmentation, and other pituitary deficits. Which pattern fits?','Secondary adrenal insufficiency',['Primary autoimmune cortical destruction','Conn syndrome','Catecholamine excess'],'The ACTH pattern and preserved mineralocorticoids localize the deficiency centrally.')]),
      u('Chronic steroid exposure and abrupt withdrawal','<p>Exogenous glucocorticoids suppress CRH/ACTH. Abrupt withdrawal after sustained exposure can leave inadequate endogenous cortisol, particularly during stress. Review dose, route, duration and the clinician-directed taper.</p><p><strong>Clarification:</strong> risk depends on exposure; current guidance generally identifies systemic treatment beyond 3–4 weeks above physiologic doses. A brief course does not automatically require lifelong replacement. '+steroid+'</p>',['steroid-hpa-suppression','withdrawal-stress-risk','steroid-exposure-individualize','temporary-recovery'],[
        q('Why can abruptly stopping chronic prednisone precipitate insufficiency?','Suppressed CRH/ACTH leaves endogenous cortisol production inadequate',['Prednisone directly destroys every adrenal permanently','Withdrawal causes autonomous aldosterone secretion','ACTH rises so high that cortisol must be excessive'],'Suppression can persist after exogenous support is removed.')
      ],[q('A patient stops months of prednisone abruptly and becomes weak and hypotensive during infection. Which concern is appropriate?','Glucocorticoid-related insufficiency progressing to crisis',['An isolated adrenal androgen excess with no cortisol problem','A guaranteed normal stress response','Primary aldosteronism causing hyperkalemia'],'Exposure and increased stress needs can combine to precipitate crisis.')]),
      u('Crisis is acute decompensation, not the slow presentation','<p>Adrenal crisis can occur in primary or central disease: stress without enough steroid coverage, abrupt withdrawal, pituitary injury/surgery, or bilateral adrenal injury.</p><p>Recognize <strong>severe hypotension/shock</strong> (sometimes resistant to initial fluids), vomiting/abdominal pain, fever, marked weakness, confusion or coma. Primary salt-wasting findings may coexist, but hyperkalemia/pigmentation are not required in every crisis.</p>',['crisis-triggers','crisis-shock','crisis-gi-fever-neuro','crisis-versus-chronic','crisis-central-possible'],[
        q('Which change suggests adrenal crisis rather than stable chronic insufficiency?','Acute severe hypotension with vomiting and altered mental status',['Months of mild fatigue alone with stable vital signs','A new isolated hirsute chin hair','Asymptomatic low libido alone'],'Crisis means dangerous acute cortisol inadequacy.'),
        q('Must adrenal crisis include hyperpigmentation and hyperkalemia?','No; central or steroid-related crisis may lack both',['Yes; their absence rules it out','Yes; ACTH must always be elevated','No; crisis must instead cause hypertension'],'The emergency can arise from more than primary cortical destruction.')
      ],[q('A patient with known insufficiency has fever, persistent vomiting, confusion, and BP 78/46. Which response priority fits?','Recognize suspected adrenal crisis and start urgent treatment',['Wait for outpatient stimulation testing next week','Assume no crisis if skin is not dark','Treat only with oral maintenance doses despite vomiting'],'The clinical emergency takes priority over confirmatory testing.')])
    ]),
    s('04-insufficiency-workup-treatment','4. Insufficiency: diagnosis, treatment, and prognosis','Objective 4. Part I slides 31, 34–53; labeled diagnostic and crisis-care clarifications.',[
      u('Stable evaluation: cortisol/ACTH and cosyntropin','<p>In a stable patient, assess cortisol with ACTH and test adrenal reserve with <strong>cosyntropin (synthetic ACTH), 250 micrograms IV/IM</strong>. Measure baseline and stimulated cortisol at 30/60 minutes.</p><p>An inadequate stimulated response supports insufficiency; interpret the cutoff using the assay/protocol.</p><p><strong>Clarification:</strong> timed morning cortisol is more useful than treating one random value as a universal rule-out. Suspected crisis follows a different, immediate-treatment pathway. '+pai+'</p>',['stable-cortisol-acth','cosyntropin250','cosyntropin30-60','inadequate-response','assay-timed-cortisol'],[
        q('What does a cosyntropin test assess?','Whether cortisol rises adequately after synthetic ACTH',['Whether dexamethasone suppresses excess cortisol','Whether aldosterone exceeds renin in hypertension','Whether urine contains catecholamine metabolites'],'Stimulation tests reserve; suppression tests excess.'),
        q('Which cosyntropin protocol is given in the lecture?','250 micrograms IV/IM with baseline and 30/60-minute cortisol measurements',['1 mg dexamethasone at 11 PM as the ACTH stimulus','A single random urine cortisol with no stimulation','24-hour plasma metanephrine infusion'],'The injected synthetic ACTH should provoke a cortisol response.')
      ],[q('A stable patient with suspected insufficiency has an equivocal baseline cortisol. What test can assess adrenal synthetic reserve?','Cosyntropin stimulation test',['Adrenal biopsy before hormone tests','Aldosterone-to-renin ratio alone','Late-night cortisol suppression as the reserve test'],'Use the appropriate stimulation test with assay-specific interpretation.')]),
      u('Locate the defect and investigate its cause','<p><strong>High ACTH + low cortisol</strong> favors primary disease; <strong>low/inappropriately normal ACTH + low cortisol</strong> favors central disease. Renin/aldosterone help identify mineralocorticoid loss.</p><p>Autoimmune adrenal antibodies and clinical history help determine etiology. CT/MRI can reveal infiltrative masses, hemorrhage, or infection-associated calcification; normal imaging does not exclude functional failure. Consider pituitary evaluation if central disease is suspected.</p>',['acth-localization','renin-aldo-workup','autoimmune-cause-workup','adrenal-imaging-selective','normal-image-not-exclude','central-pituitary-workup'],[
        q('How can ACTH help localize confirmed cortisol deficiency?','High ACTH favors adrenal failure; low/inappropriately normal ACTH favors central disease',['Low ACTH always proves adrenal destruction','High ACTH always proves a medullary tumor','ACTH cannot provide localization information'],'Interpret the target hormone and its driving signal together.'),
        q('What does normal adrenal imaging mean in suspected insufficiency?','It does not exclude a functional hormone deficiency',['It rules out every autoimmune cause','It proves normal cosyntropin response','It means cortisol and ACTH need not be measured'],'Imaging is useful selectively for cause, not a substitute for functional testing.')
      ],[q('A patient has confirmed low cortisol with elevated ACTH and high renin/low aldosterone. Imaging shows no mass. Which conclusion fits?','Primary insufficiency remains plausible; evaluate causes such as autoimmunity',['A normal image reverses the hormonal diagnosis','The low cortisol must be pituitary-dependent excess','Renin proves autonomous aldosterone secretion'],'Hormonal failure can occur without a visible adrenal mass.')]),
      u('Maintenance glucocorticoid replacement','<p><strong>Hydrocortisone (Cortef) 15–25 mg/day</strong>, divided with the larger dose in the morning, approximates physiologic cortisol timing. Adjust using energy, weight, postural BP, and signs of too little or too much replacement.</p><p>Drug interactions matter: increased metabolism (e.g., rifampin) can reduce exposure; reduced clearance can increase it. Avoid both underreplacement and chronic Cushingoid overreplacement.</p>',['hydrocortisone15-25','morning-larger','replacement-clinical-monitor','steroid-clearance-interactions'],[
        q('Which adult maintenance hydrocortisone schedule fits the lecture?','15–25 mg/day divided, with the larger dose in the morning',['100 mg IV every hour indefinitely','A larger midnight dose to reverse the normal rhythm','Only fludrocortisone with no glucocorticoid'],'Maintenance replacement differs from stress/crisis dosing.'),
        q('What can happen when rifampin increases hydrocortisone metabolism?','Lower steroid exposure may require a clinician-directed adjustment',['Hydrocortisone exposure must increase','No interaction can occur with replacement steroids','Aldosterone necessarily becomes autonomous'],'Faster clearance can make an otherwise adequate regimen insufficient.')
      ],[q('A replacement-treated patient develops weight gain, easy bruising, and Cushingoid changes. What should be reviewed?','Possible glucocorticoid overreplacement and dose adjustment',['Automatic doubling of the maintenance dose','Stopping all steroid abruptly without review','Adding mineralocorticoid solely to treat the bruising'],'Replacement aims for adequacy without chronic excess.')]),
      u('Mineralocorticoids when aldosterone is deficient','<p><strong>Fludrocortisone (Florinef)</strong> replaces deficient aldosterone; the lecture gives <strong>0.05–0.1 mg/day</strong>. Monitor postural symptoms/BP, Na/K, edema and salt craving; adjust accordingly.</p><p><strong>Scope clarification:</strong> destructive primary disease often requires both steroid types; central/steroid-induced insufficiency generally needs glucocorticoid alone. Mineralocorticoid stress-dose increases are not routinely required.</p>',['fludrocortisone005-01','fludro-bp-na-k-edema','primary-both-central-gluco','no-fludro-stress-dose'],[
        q('When is fludrocortisone replacement indicated?','When mineralocorticoid/aldosterone deficiency is present',['Automatically for every central cortisol deficiency','Only to suppress ACTH in Cushing disease','To block aldosterone in Conn syndrome'],'Match replacement to the hormone actually deficient.'),
        q('Which findings guide fludrocortisone adjustment?','Postural BP/symptoms, Na/K, salt craving, and edema',['Only the size of a pituitary lesion','Only late-night salivary cortisol','Only urine metanephrine levels'],'Assess both adequate salt-volume support and excess fluid retention.')
      ],[q('A patient with isolated secondary adrenal insufficiency has preserved aldosterone and normal K. Is fludrocortisone routinely required?','No; replace cortisol and manage the central cause',['Yes; all insufficiency always destroys aldosterone','Yes; use it instead of hydrocortisone','No; no steroid of any kind is needed'],'Mineralocorticoid production usually remains supported by RAAS.')]),
      u('Stress coverage and prevention of crisis','<p>Use <strong>medical-alert identification</strong>, a written sick-day plan, and an emergency hydrocortisone injection kit with training. Minor illness may require temporarily increased oral glucocorticoid per the plan; major stress needs parenteral coverage.</p><p><strong>Clarification:</strong> persistent vomiting/inability to retain medicine or instability needs injected steroid and urgent assessment, not repeated oral doses alone. '+steroid+'</p>',['medical-alert-injection','sickday-minor-major','vomiting-parenteral-urgent','avoid-abrupt-withdrawal'],[
        q('Which preparation helps prevent an avoidable adrenal crisis?','Medical alert, sick-day instructions, and emergency injection training',['Stopping needed cortisol replacement whenever appetite falls','Using one fixed maintenance dose through every major surgery','Replacing steroid education with annual imaging only'],'Patients need a practical response to increased needs or failed oral intake.')
      ],[q('A patient with Addison disease cannot keep oral hydrocortisone down because of repeated vomiting. Which response fits?','Use the prescribed emergency injection plan and seek urgent medical care',['Keep repeating oral doses without escalation','Skip all steroids until vomiting ends','Take only extra fludrocortisone'],'Failure to absorb glucocorticoid during illness can precipitate crisis.')]),
      u('Crisis: treat immediately while investigating','<p>Draw cortisol/ACTH and standard labs if this causes <strong>no delay</strong>. Give <strong>hydrocortisone 100 mg IV/IM immediately</strong>, isotonic IV fluids, and correct glucose/electrolyte problems; assess/treat the trigger.</p><p><strong>Current dosing clarification:</strong> continue hydrocortisone <strong>200 mg/24 hours</strong> by infusion or <strong>50 mg every 6 hours</strong>. Taper after clinical recovery under specialist guidance, rather than by a fixed schedule regardless of illness. High-dose hydrocortisone supplies mineralocorticoid activity; resume needed maintenance fludrocortisone as stress doses fall. '+crisis+'</p>',['crisis-no-delay','crisis-hydro100','crisis200-or50q6','crisis-fluids-glucose-electrolytes','crisis-treat-trigger','crisis-recovery-taper-mineral'],[
        q('What is the immediate steroid dose for suspected adult adrenal crisis?','Hydrocortisone 100 mg IV/IM',['Hydrocortisone 15 mg orally only despite shock','Fludrocortisone as the sole emergency steroid','Wait for cosyntropin results before any steroid'],'Do not delay treatment for laboratory confirmation.'),
        q('Which ongoing crisis regimen matches current guidance after the initial hydrocortisone dose?','200 mg/24 hours or 50 mg every 6 hours',['15 mg total per week','An unrestricted escalation every hour without monitoring','Only an extra bedtime maintenance tablet'],'Continue stress coverage while resuscitating and treating the trigger.')
      ],[q('A steroid-dependent patient is hypotensive, confused, and vomiting during sepsis. Labs have been drawn. What comes next?','Immediate parenteral hydrocortisone plus IV fluids and treatment of the precipitant',['Wait for all hormone results','Oral fludrocortisone alone and discharge','Dexamethasone suppression testing to confirm crisis'],'The emergency requires both steroid and circulatory support.')]),
      u('Prognosis depends on replacement and rapid crisis care','<p>Prompt crisis recognition/treatment greatly improves outcome. Untreated deficiency can be fatal; ongoing disease carries risk from future stressors.</p><p>Permanent primary cortical destruction generally requires <strong>lifelong replacement</strong>. <strong>Clarification:</strong> some central/steroid-related suppression can recover, so not every patient has permanent deficiency. Follow-up, safe taper/reassessment, and prevention remain important.</p>',['crisis-prompt-outcome','insufficiency-lifelong-primary','central-recovery-possible','prognosis-stress-followup'],[
        q('Which prognosis statement correctly distinguishes insufficiency types?','Permanent primary destruction usually needs lifelong replacement; steroid-related suppression may recover',['Every brief steroid course causes permanent failure','All Addison disease resolves without replacement','Crisis treatment can safely wait because the prognosis is always benign'],'Duration depends on the underlying cause.')
      ],[q('A patient recovering from steroid-induced insufficiency asks whether replacement is necessarily lifelong. Which answer fits?','Recovery is possible; follow a clinician-directed taper and reassessment',['Yes, every suppressed HPA axis is irreversibly destroyed','No, stop today without evaluation','Recovery means no need for stress precautions during reassessment'],'Potential recovery requires planned assessment rather than abrupt withdrawal.')])
    ]),
    s('05-cortisol-excess','5. Endogenous cortisol excess: mechanisms and findings','Objective 5. Part I slides 57–72, 91.',[
      u('Cushing syndrome versus Cushing disease','<p><strong>Cushing syndrome</strong> means glucocorticoid excess; review exogenous steroid exposure first. For endogenous excess, the lecture describes three sources:</p><ul><li><strong>Pituitary ACTH adenoma</strong> (most common endogenous source): specifically <strong>Cushing disease</strong>.</li><li><strong>Ectopic ACTH</strong>: e.g., small-cell lung cancer or carcinoid/neuroendocrine tumors.</li><li><strong>Autonomous adrenal cortisol</strong>: adenoma, carcinoma, or bilateral hyperplasia; ACTH is suppressed.</li></ul>',['cushing-syndrome-disease','cushing-exogenous-review','cushing-pituitary-common','cushing-ectopic','cushing-adrenal-independent'],[
        q('Which diagnosis is specifically called Cushing disease?','Pituitary ACTH-producing adenoma causing cortisol excess',['Every adrenal cortisol-producing adenoma','All exogenous glucocorticoid exposure','Every ectopic ACTH-producing lung tumor'],'Cushing disease is one cause of the broader syndrome.'),
        q('Which endogenous cortisol-excess source is ACTH-independent?','Autonomous adrenal cortisol secretion',['Pituitary corticotroph adenoma','Ectopic ACTH-secreting small-cell lung cancer','Hypothalamic stimulation of pituitary ACTH'],'Autonomous adrenal cortisol suppresses normal ACTH through feedback.')
      ],[q('A patient has confirmed cortisol excess with suppressed ACTH. Which source category fits best?','Autonomous adrenal cortisol production',['Pituitary ACTH hypersecretion','Ectopic ACTH hypersecretion','Primary adrenal insufficiency'],'Suppressed ACTH directs the localization toward the adrenal source.')]),
      u('Skin and fat-distribution clues','<p>Recognize <strong>broad violaceous striae, thin/easily bruised skin, and slow wound healing/infections</strong>.</p><p>Fat redistributes centrally: abdominal obesity, rounded plethoric <strong>moon face</strong>, dorsocervical <strong>buffalo hump</strong>, and supraclavicular fat pads. Limbs can look thin from muscle wasting; women may develop hirsutism.</p>',['cushing-striae-bruising','cushing-wound-infection','cushing-central-moon-hump','cushing-thin-limbs-hirsutism'],[
        q('Which appearance most supports a Cushingoid pattern?','Central obesity, moon face, supraclavicular/dorsocervical fat, and thin limbs',['General weight loss with dark pressure-area creases','Only lower-body pear-shaped adiposity without other findings','Isolated edema with no skin or muscle changes'],'Fat redistribution plus catabolic findings is more informative than obesity alone.'),
        q('Which skin findings are characteristic of cortisol excess?','Violaceous striae, easy bruising, and poor healing',['Vitiligo with obligatory salt craving','Only pale skin during episodic hypertension','Only dry skin without bruising or striae'],'Cortisol excess weakens connective tissue and suppresses repair/immunity.')
      ],[q('A patient has new broad purple striae, easy bruising, thin skin, and infections with central weight gain. Which endocrine process should be evaluated?','Glucocorticoid excess',['Isolated hypoaldosteronism','Adrenal androgen deficiency alone','A catecholamine disorder as the only explanation'],'The combined tissue/fat findings are characteristic and warrant evaluation.')]),
      u('Metabolic, muscle, and bone consequences','<p>Cortisol excess contributes to <strong>hypertension and diabetes/hyperglycemia</strong>. Protein catabolism causes <strong>proximal hip/shoulder weakness</strong>.</p><p>Bone/connective-tissue effects include <strong>osteoporosis/fractures and avascular necrosis</strong>; renal stones may occur. These are important complications, not merely changes in appearance.</p>',['cushing-htn-diabetes','cushing-proximal-weakness','cushing-osteoporosis-avn','cushing-stones'],[
        q('Which muscle pattern is typical of cortisol excess?','Proximal hip and shoulder weakness',['Only distal stocking-glove sensory loss','Only an isolated cranial nerve palsy','Increased muscle bulk and strength from protein synthesis'],'Catabolism affects large proximal muscle groups.'),
        q('Which complications are associated with sustained cortisol excess?','Hypertension, diabetes, osteoporosis, and avascular necrosis',['Only hypoglycemia and universal potassium retention','Only painless incidental adrenal imaging changes','Only an isolated elevated renin without systemic effects'],'Excess cortisol affects metabolism, circulation, and bone.')
      ],[q('A patient with Cushingoid features has difficulty rising from a chair and a low-trauma fracture. Which mechanism fits?','Cortisol-associated muscle catabolism and bone loss',['Aldosterone deficiency directly enlarging muscles','Catecholamines strengthening bone','Normal cortisol producing no tissue effects'],'Weakness and fracture can be part of the same cortisol-excess process.')]),
      u('Reproductive, neuropsychiatric, and survival effects','<p>Oligo/amenorrhea, impotence, low libido and reduced fertility can occur. Headache, psychiatric illness and cognitive changes may accompany the physical findings.</p><p>Untreated sustained excess increases cardiovascular and diabetes complications, opportunistic infections/poor healing, and fracture risk. Effective source-directed treatment matters.</p>',['cushing-reproductive','cushing-psychiatric-cognitive','cushing-morbidity-mortality'],[
        q('Which nonappearance findings can accompany cortisol excess?','Menstrual/libido/fertility changes and psychiatric/cognitive symptoms',['Only excess fertility with no mood effects','Only salt craving with obligatory hyperpigmentation','Only episodic palpitations without other effects'],'The syndrome affects reproductive and neurologic/psychiatric function too.')
      ],[q('A patient with established cortisol excess asks why treatment matters beyond appearance. What explanation fits?','It reduces the burden of cardiovascular, metabolic, infectious, and bone complications',['The condition affects only cosmetic fat distribution','No complication risk exists if the patient is comfortable','Cortisol excess is protective against all infections'],'Persistent excess causes meaningful morbidity and can increase mortality.')])
    ]),
    s('06-cortisol-testing-order','6. Cortisol excess: confirm first, then localize','Objective 6. Part I slides 73–79; a labeled correction replaces random urine testing.',[
      u('First: establish excess with an appropriate screening test','<p>Review exogenous steroids, then select an appropriate cortisol-excess test. <strong>Overnight dexamethasone:</strong> 1 mg orally at 11 PM, cortisol at 8 AM; failure to suppress suggests excess.</p><p>Anticonvulsants/rifampin can alter dexamethasone clearance; estrogen/pregnancy can alter interpretation. Abnormal testing needs corroboration and specialist evaluation before source imaging. '+cushing+'</p>',['cushing-exposure-first','dst1mg11pm8am','dst-failure-suppression','dst-interferences','confirm-before-localize'],[
        q('What result suggests an abnormal overnight dexamethasone suppression test?','Morning cortisol fails to suppress after nighttime dexamethasone',['Cortisol appropriately becomes low','ACTH rises only after cosyntropin as the same test','Urinary aldosterone is low'],'Normally dexamethasone suppresses pituitary drive and morning cortisol.'),
        q('Which testing sequence fits suspected endogenous cortisol excess?','Confirm biochemical excess, then use ACTH to guide localization',['Find any pituitary nodule first and assume it is functional','Perform adrenal surgery before hormone testing','Use a single random cortisol as definitive source localization'],'Incidental lesions can mislead if imaging precedes biochemical diagnosis.')
      ],[q('A patient takes phenytoin and has an abnormal dexamethasone test. What should be considered before labeling the source?','Drug-related test interference and appropriate corroborating testing',['Phenytoin proves adrenal carcinoma','Immediate pituitary surgery without confirmation','Ignore medication exposure in all suppression testing'],'Altered dexamethasone metabolism can change suppression-test results.')]),
      u('Late-night salivary cortisol and urinary free cortisol','<p><strong>Late-night saliva:</strong> excess can erase the expected cortisol nadir. Repeat collections improve reliability; shift work, disturbed sleep, stress and illness can confound timing/results.</p><p><strong>Urine-test correction:</strong> use <strong>24-hour urinary free cortisol</strong> with collection adequacy assessed (usually repeated), not the slide’s random cortisol-to-creatinine “3×” rule. Interpret with collection quality and renal function. '+cushing+'</p>',['salivary-nadir-repeat','salivary-sleep-stress','ufc24h-not-random','ufc-collection-renal'],[
        q('Why can high late-night salivary cortisol support excess?','It suggests loss of the normal late-night cortisol nadir',['Cortisol should normally be highest at 11 PM','Saliva directly proves the tumor location','It measures aldosterone rather than cortisol'],'Use the expected circadian pattern with attention to sleep schedule.'),
        q('Which urine test is the guideline-supported cortisol-excess screen?','24-hour urinary free cortisol, with adequate/repeated collection',['A random urine cortisol-to-creatinine “3×” rule','Urine ketones as a cortisol assay','Aldosterone-to-renin ratio from urine only'],'The lecture’s random-ratio description should not be memorized as a diagnostic rule.')
      ],[q('A shift worker collects “late-night” saliva during the middle of their usual waking shift. How should the clinician respond?','Consider the altered sleep rhythm and select/interpret testing appropriately',['Any elevated value is definitive regardless of sleep','The sample proves a pituitary source','A random urine ratio automatically resolves the diagnosis'],'Choose a reliable test for the patient’s actual circumstances.')]),
      u('Second: ACTH separates dependent and independent excess','<p>After confirming hypercortisolism, measure <strong>ACTH</strong>.</p><ul><li><strong>Suppressed ACTH:</strong> autonomous adrenal source → adrenal evaluation.</li><li><strong>High/inappropriately normal ACTH:</strong> ACTH-dependent excess → differentiate pituitary from ectopic ACTH.</li></ul><p>A normal-range ACTH may still be inappropriate when cortisol is high.</p>',['acth-suppressed-adrenal','acth-dependent-pituitary-ectopic','acth-inappropriate-normal'],[
        q('In confirmed hypercortisolism, what does suppressed ACTH suggest?','An ACTH-independent adrenal source',['An ACTH-producing pituitary adenoma as the required cause','An ectopic ACTH tumor as the required cause','Normal adrenal feedback with no excess'],'High autonomous cortisol suppresses normal pituitary ACTH.'),
        q('What source distinction is needed when excess cortisol is ACTH-dependent?','Pituitary ACTH versus ectopic ACTH',['Adrenal cortex versus aldosterone deficiency only','Primary versus secondary hypothyroidism only','Benign kidney cyst versus diabetic nephropathy'],'Both pituitary and ectopic tumors can drive adrenal cortisol production.')
      ],[q('Biochemical cortisol excess is confirmed. ACTH is undetectable. Which imaging target is appropriate?','Adrenal glands',['Pituitary alone regardless of ACTH','Thyroid alone','No source evaluation because ACTH is low'],'The hormone sequence directs localization rather than scanning indiscriminately.')]),
      u('Third: distinguish ACTH sources, then image','<p><strong>Lecture CRH test:</strong> a rise in ACTH/cortisol favors pituitary disease; little/no response favors ectopic ACTH. <strong>Clarification:</strong> responses are supportive rather than perfectly definitive; specialist localization may require additional testing.</p><p>Biochemical evidence for pituitary disease → <strong>pituitary MRI</strong>. Ectopic-source search → <strong>chest/abdomen/pelvis imaging</strong>, with selected functional imaging if not found. Small nonfunctioning pituitary lesions are common enough that an image alone does not establish the source.</p>',['crh-pituitary-rise','crh-ectopic-no-rise','crh-not-definitive','pituitary-mri-after-biochem','ectopic-imaging-functional','incidental-pituitary-not-proof'],[
        q('In the lecture’s CRH source-localization pattern, what favors a pituitary source?','ACTH and cortisol increase after CRH',['ACTH/cortisol remain unchanged as the classic pituitary response','Aldosterone falls after sodium intake','Urine metanephrines normalize after CRH'],'Pituitary corticotroph tissue may respond to CRH; this is not infallible.'),
        q('Why should a small pituitary lesion not automatically be called the cortisol-excess source?','It may be incidental and nonfunctioning',['Every pituitary lesion secretes ACTH','Pituitary MRI replaces biochemical confirmation','Ectopic ACTH can never coexist with an incidental pituitary finding'],'Correlate localization evidence with imaging.')
      ],[q('Confirmed ACTH-dependent excess has a CRH response favoring ectopic production. Which source search matches the lecture?','Chest/abdomen/pelvis imaging for an ectopic tumor',['Adrenalectomy solely because ACTH is elevated','Assume any tiny pituitary lesion is diagnostic','Stop evaluation after a normal adrenal ultrasound'],'Investigate likely ectopic sources such as lung or GI neuroendocrine tumors.')])
    ]),
    s('07-cortisol-source-treatment','7. Treat cortisol excess by its source','Objective 7. Part I slides 82–89.',[
      u('Pituitary ACTH adenoma','<p><strong>Transsphenoidal pituitary resection</strong> by an experienced surgical team is the main treatment for Cushing disease. Surgery may affect other pituitary functions.</p><p>Persistent/recurrent disease may need repeat surgery, radiation, or medical management with specialist follow-up. Post-treatment cortisol function must be reassessed.</p>',['pituitary-transsphenoidal','pituitary-repeat-radiation','posttreatment-hormone-review'],[
        q('What is the main source-directed treatment for pituitary Cushing disease?','Transsphenoidal resection of the ACTH adenoma',['Unilateral adrenal surgery as the automatic first choice','Fludrocortisone as the cortisol-suppressing drug','Alpha blockade alone'],'Remove the ACTH-driving pituitary lesion when feasible.')
      ],[q('A localized pituitary ACTH adenoma causes confirmed Cushing disease. Which referral/treatment fits?','Experienced pituitary surgical team for transsphenoidal resection',['Resect an unrelated adrenal nodule without localization','Treat with fludrocortisone only','Ignore other pituitary function after surgery'],'Source-directed surgery and hormonal follow-up are needed.')]),
      u('Adrenal cortisol sources','<p><strong>Unilateral cortisol-producing adenoma:</strong> adrenalectomy, often laparoscopic. <strong>Suspected adrenal carcinoma:</strong> oncologic resection, often open, with specialist planning.</p><p>Bilateral cortisol-producing disease requires a subtype-specific plan; bilateral removal causes permanent adrenal insufficiency. Assess postoperative steroid needs because prior excess can suppress normal HPA function.</p>',['adrenal-adenoma-resection','adrenal-carcinoma-oncology','bilateral-source-plan','postadrenal-steroid-needs'],[
        q('Which source-directed treatment fits a unilateral cortisol-producing adrenal adenoma?','Resection of the affected adrenal lesion',['Transsphenoidal surgery for every adrenal adenoma','Doxazosin as definitive cortisol treatment','Treat only the high glucose and leave the source unassessed'],'The adrenal lesion is the autonomous cortisol source.'),
        q('What is a major consequence of bilateral adrenalectomy?','Permanent need for adrenal hormone replacement',['Permanent autonomous ACTH-independent cortisol excess','Elimination of all steroid needs','Selective loss of thyroid hormone only'],'Removing both adrenal cortices removes essential hormone production.')
      ],[q('After removal of a cortisol-producing adrenal adenoma, why might glucocorticoid replacement be needed temporarily?','Prior excess suppressed the remaining HPA/adrenal function',['Cortisol replacement is never needed after unilateral surgery','The remaining adrenal must immediately produce excess aldosterone','The removed medulla was the only source of ACTH'],'Plan for postoperative insufficiency while function recovers.')]),
      u('Ectopic ACTH and unresectable/occult disease','<p>Remove a resectable ectopic ACTH source when feasible, such as a localized neuroendocrine tumor. For aggressive cancers such as SCLC, cancer-directed systemic therapy may be appropriate.</p><p>If the source is occult or cannot be controlled promptly, specialist medical suppression of cortisol production can be used; the lecture names <strong>ketoconazole</strong>. Monitor treatment toxicity and continue source evaluation. Prognosis depends on both cortisol control and the underlying tumor.</p>',['ectopic-resectable-surgery','sclc-cancer-therapy','occult-medical-ketoconazole','medical-toxicity-search','source-prognosis'],[
        q('What is the role of ketoconazole in the lecture’s cortisol-excess management?','Medical suppression of steroidogenesis when source control is not promptly feasible',['Mineralocorticoid replacement in Addison disease','First-line alpha blockade for pheochromocytoma','Confirmation of an aldosterone-producing adenoma'],'This is cortisol-lowering therapy, requiring specialist monitoring.'),
        q('Which treatment principle fits ectopic ACTH from an aggressive lung cancer?','Control cortisol and treat the cancer with appropriate oncology therapy',['Pituitary surgery regardless of the proven source','Fludrocortisone alone to stop ACTH secretion','No tumor-directed treatment if BP is controlled'],'The primary malignancy determines feasible source control and prognosis.')
      ],[q('Cortisol excess is confirmed from an ectopic source that has not yet been localized. Which strategy fits?','Medical cortisol control with specialist monitoring while continuing the source search',['Blind pituitary resection based only on high ACTH','Give permanent high-dose hydrocortisone to reduce cortisol','Stop imaging follow-up because the first CT is negative'],'Manage the harmful hormone excess while investigating its cause.')])
    ]),
    s('08-hypoaldosteronism','8. Hypoaldosteronism: causes and pathophysiology','Objective 8. Part II slides 5–9.',[
      u('Low renin from kidney disease → low aldosterone','<p>The common lecture mechanism is <strong>hyporeninemic hypoaldosteronism</strong>: diabetic nephropathy or chronic tubulointerstitial kidney disease reduces renin drive, reducing aldosterone.</p><p>Less aldosterone action impairs renal K/H handling → <strong>hyperkalemia and hyperchloremic non-anion-gap metabolic acidosis</strong>, often termed <strong>type 4 RTA</strong>. Primary adrenal cortical failure is another aldosterone-deficiency cause.</p>',['hypoaldo-low-renin','hypoaldo-diabetic-tubulointerstitial','hypoaldo-k-h-mechanism','type4-nongap-hyperchloremic','hypoaldo-primary-other'],[
        q('What is the common hypoaldosteronism mechanism emphasized by this lecture?','Reduced renin production in diabetic/chronic tubulointerstitial kidney disease',['Autonomous aldosterone-producing adenoma','Excess pituitary ACTH alone','High renin stimulating normal aldosterone production'],'The defect can originate in renal signaling rather than adrenal destruction.'),
        q('Which lab pattern is characteristic of type 4 RTA from reduced aldosterone action?','Hyperkalemia and hyperchloremic non-anion-gap acidosis',['Hypokalemia with metabolic alkalosis','Marked ketonemia with normal potassium as its definition','Hypernatremia with obligatory respiratory alkalosis'],'Reduced distal electrolyte handling explains the pattern.')
      ],[q('A patient with diabetic nephropathy has persistent high K, low renin, low aldosterone, and non-gap acidosis. Which process fits?','Hyporeninemic hypoaldosteronism/type 4 RTA',['Primary aldosteronism','Ectopic ACTH excess','Pheochromocytoma'],'The renal signaling failure and lab pattern align.')]),
      u('Often subtle symptoms; potassium is the important clue','<p>Patients may have few symptoms. Sodium is often normal because other mechanisms conserve salt; do not require dramatic Addison-like salt wasting.</p><p>Suspect the disorder with <strong>persistent otherwise unexplained hyperkalemia</strong> in the right context. Recheck/assess causes promptly and evaluate severe hyperkalemia/ECG changes urgently.</p>',['hypoaldo-few-symptoms','hypoaldo-na-normal','hypoaldo-persistent-k','hypoaldo-severe-k-urgent'],[
        q('Why can hypoaldosteronism be clinically subtle?','Other sodium-conserving mechanisms can limit obvious salt wasting',['Potassium cannot rise without severe pain','Normal sodium guarantees normal aldosterone action','Every affected patient has marked hyperpigmentation'],'A normal sodium value does not remove the potassium/acid-base problem.')
      ],[q('A patient with kidney disease feels well but repeated K remains elevated and bicarbonate is low with a normal gap. Should normal Na dismiss hypoaldosteronism?','No; the potassium/acid-base pattern remains compatible',['Yes; normal Na rules out any aldosterone problem','Yes; symptoms must always include shock','No; it instead proves cortisol excess'],'Subtle presentation requires attention to the biochemical pattern.')])
    ]),
    s('09-hypoaldo-treatment','9. Treat hypoaldosteronism','Objective 9. Part II slides 9–10.',[
      u('Treatment depends on primary adrenal versus renal cause','<p><strong>Primary adrenal aldosterone deficiency:</strong> fludrocortisone replaces the missing mineralocorticoid, guided by orthostasis/BP and K.</p><p><strong>Hyporeninemic hypoaldosteronism:</strong> reduce dietary K, review contributing medicines, and consider a <strong>loop/thiazide diuretic</strong> when appropriate. Fludrocortisone can worsen <strong>hypertension/edema</strong>, so it is not the routine choice in that group.</p>',['hypoaldo-primary-fludro','hypoaldo-low-k-diet','hypoaldo-diuretic-med-review','fludro-hypertension-edema'],[
        q('Why is fludrocortisone often avoided in hyporeninemic hypoaldosteronism with hypertension/edema?','It can worsen sodium-volume retention and BP',['It always causes potassium retention','It has no mineralocorticoid action','It selectively removes excess cortisol'],'Treat potassium while accounting for the patient’s volume/BP status.'),
        q('Which lecture treatment fits appropriate hyporeninemic hypoaldosteronism care?','Low-potassium diet, with a loop/thiazide diuretic when suitable',['A high-potassium diet and mandatory salt loading','Adrenalectomy for every low-renin kidney disorder','Doxazosin as the sole potassium treatment'],'The goal differs from replacing all adrenal hormones in primary failure.')
      ],[q('A hypertensive edematous patient with diabetic kidney disease has chronic hyporeninemic hypoaldosteronism. Which lecture plan is preferable to routine fludrocortisone?','Reduce potassium intake and consider an appropriate diuretic/medication review',['Give fludrocortisone without reviewing BP/edema','Remove a normal adrenal gland','Give ketoconazole to inhibit more steroid synthesis'],'Avoid worsening the existing sodium-volume burden.')]),
      u('Severe potassium elevation needs an acute pathway','<p>The lecture advises prompt repeat K and <strong>ECG evaluation when markedly elevated (e.g., &gt;6)</strong>. ECG changes or significant hyperkalemia require acute assessment/treatment rather than waiting for dietary change alone.</p><p>Exclude other medication/renal causes and involve nephrology for unexplained or complex cases. Continue long-term glucose/BP and kidney care.</p>',['hyperk-repeat-ecg','hyperk-acute-not-diet-only','hypoaldo-nephrology-kidney-care'],[
        q('Which action fits marked hyperkalemia in suspected hypoaldosteronism?','Prompt reassessment/ECG and acute treatment as indicated',['Wait several weeks for diet change regardless of ECG','Assume potassium is harmless if sodium is normal','Use only a dexamethasone suppression test'],'The immediate cardiac risk takes priority.')
      ],[q('An outpatient with suspected hypoaldosteronism has confirmed K 6.6 and ECG changes. Which response is appropriate?','Urgent hyperkalemia management, not dietary counseling alone',['Schedule only routine follow-up next month','Ignore because the patient has no symptoms','Give additional potassium before any evaluation'],'Severe hyperkalemia is a separate emergency within the chronic disorder.')])
    ]),
    s('10-hyperaldosteronism','10. Hyperaldosteronism: causes, epidemiology, presentation','Objective 10. Part II slides 11–18.',[
      u('Primary autonomous aldosterone: bilateral or unilateral','<p><strong>Primary aldosteronism (Conn syndrome)</strong> is aldosterone secretion that is inappropriate for/suppresses renin. Common sources: <strong>bilateral adrenal hyperplasia</strong> and <strong>aldosterone-producing adenoma</strong>; adrenal carcinoma is rare.</p><p>The lecture emphasizes adults around <strong>30–50</strong>, more women than men, and a potentially treatable cause of secondary HTN. Its stated subtype proportions are approximate teaching figures, not required to recognize the disease.</p>',['pa-autonomous-renin','pa-bilateral-adenoma','pa-carcinoma-rare','pa-epi-age-sex','pa-treatable-htn'],[
        q('Which two sources commonly cause primary aldosteronism?','Bilateral adrenal hyperplasia and aldosterone-producing adenoma',['Autoimmune cortex destruction and pituitary ACTH deficiency','TB destruction and steroid withdrawal','Pheochromocytoma and prolactinoma'],'Both sources can produce aldosterone independent of normal renin drive.'),
        q('What epidemiologic pattern does the lecture emphasize for primary aldosteronism?','Adults around 30–50, with female predominance',['Only newborns with ambiguous genitalia','Only older men with no hypertension','Only people with permanent cortisol deficiency'],'The pattern is a clue, not an exclusion rule for other patients.')
      ],[q('A 38-year-old woman has resistant hypertension and suppressed renin with inappropriate aldosterone. Which lecture disease fits?','Primary aldosteronism',['Hyporeninemic hypoaldosteronism','Primary adrenal insufficiency','A nonfunctioning adrenal mass as a complete explanation'],'Age and presentation support evaluating autonomous aldosterone secretion.')]),
      u('Aldosterone excess: hypertension, K loss, alkalosis','<p>Na/water retention raises BP, usually <strong>without marked hypernatremia</strong>. Renal K/H losses can cause <strong>hypokalemia and metabolic alkalosis</strong>.</p><p>Hypokalemia is <strong>not universal</strong>; normokalemia must not exclude the diagnosis. Resistant/severe hypertension or spontaneous/diuretic-associated hypokalemia are particularly strong clues.</p>',['pa-htn-na-not-high','pa-hypok-alkalosis','pa-normok-possible','pa-resistant-hypok-clues'],[
        q('Which lab/BP pattern is classic for primary aldosteronism?','Hypertension with low K and metabolic alkalosis',['Hypotension with high K and acidosis','Shock with low cortisol and high ACTH','Normal BP with obligatory severe hyponatremia'],'Aldosterone retains volume and promotes K/H excretion.'),
        q('Does normal potassium rule out primary aldosteronism?','No; many patients are normokalemic',['Yes; all affected patients must have severe hypokalemia','Yes; aldosterone cannot raise BP without low K','No; instead it proves an adrenal carcinoma'],'Use the overall hypertension/hormone context.')
      ],[q('A patient’s BP remains high on several drugs, but K is normal. Is an aldosterone evaluation necessarily unnecessary?','No; resistant hypertension can warrant screening despite normal K',['Yes; low K is an absolute requirement','Yes; normal K proves normal renin','No; diagnose PA without hormone testing'],'Hypokalemia is a useful clue, not a mandatory feature.')]),
      u('Symptoms and cardiovascular consequences','<p>K-related symptoms: fatigue/weakness, nocturia, and with more severe depletion polyuria/polydipsia, paresthesias or intermittent paralysis. Headache can accompany high BP.</p><p>Severe BP elevation can injure retinal, renal and cardiac tissue or cause encephalopathy. PA increases <strong>stroke, atrial fibrillation and MI risk</strong> beyond BP alone. Compare with other secondary-HTN causes such as renovascular disease or cortisol excess.</p>',['pa-weakness-nocturia','pa-severe-k-neuromuscular','pa-endorgan-encephalopathy','pa-cv-stroke-af-mi','pa-secondary-htn-differential'],[
        q('Which symptoms can reflect potassium depletion in aldosterone excess?','Weakness, polyuria/nocturia, and in severe cases paresthesias or paralysis',['Only new skin hyperpigmentation','Only loss of libido with normal electrolytes','Only vomiting from every meal with no BP changes'],'Symptoms reflect both K loss and hypertension.'),
        q('Why identify primary aldosteronism beyond treating its BP reading?','It carries excess stroke, AF, and MI risk and has targeted treatment',['It is always an incidental harmless lab finding','It protects against cardiac disease','It can only be managed with nonspecific BP drugs'],'Source-specific therapy addresses the harmful aldosterone process.')
      ],[q('A patient with confirmed PA asks why targeted treatment matters when another antihypertensive could lower BP. Which explanation fits?','Aldosterone excess contributes additional cardiovascular risk and can be treated specifically',['Only the BP number matters and the hormone has no other impact','PA always resolves spontaneously','PA never produces end-organ injury'],'The disorder is clinically consequential beyond one measurement.')])
    ]),
    s('11-pa-screen-treatment','11. Aldosteronism screening and subtype-based treatment','Objective 11. Part II slides 17–26; brief guideline clarifications.',[
      u('Initial screen: aldosterone, renin, and ARR','<p>Measure <strong>plasma aldosterone and renin</strong>, calculate the <strong>aldosterone-to-renin ratio (ARR)</strong>, and interpret both absolute levels. Correct hypokalemia because it can falsely lower aldosterone; review interfering medication with a safe testing plan.</p><p>Lecture high-priority groups: resistant HTN; HTN with hypokalemia, adrenal incidentaloma, sleep apnea, early-onset/family stroke history, affected first-degree relatives, or young-onset AF. <strong>Update:</strong> 2025 guidance conditionally suggests screening all hypertensive adults where feasible. '+aldo+'</p>',['arr-initial','arr-absolute-values','arr-correct-k','arr-med-safety','pa-screen-groups','pa-screen-2025-context'],[
        q('What is the initial hormonal screen for primary aldosteronism?','Aldosterone and renin with calculation of ARR',['Adrenal MRI before hormones','Random cortisol alone','Urine catecholamines alone'],'ARR is interpreted with aldosterone and renin, not as an isolated number.'),
        q('Why correct hypokalemia before aldosterone screening?','Low K can suppress aldosterone and create a misleadingly low result',['Low K always falsely raises aldosterone','K cannot affect aldosterone release','It eliminates the need to measure renin'],'Potassium status affects secretion and interpretation.'),
        q('Which normokalemic hypertensive patient is a lecture screening priority?','A patient with resistant hypertension and sleep apnea',['Only a patient with documented high cortisol','Only a patient with severe hyponatremia','No normokalemic patient can merit testing'],'The lecture gives several indications beyond low K.')
      ],[q('A patient with HTN and hypokalemia is scheduled for ARR testing while taking interfering medications. Which preparation fits?','Correct K and plan medication handling with the clinician while maintaining safe BP control',['Stop every BP drug abruptly without supervision','Skip renin because K is low','Use an adrenal image as the hormonal screen'],'Testing preparation must preserve patient safety and interpretability.')]),
      u('Interpret, confirm when appropriate, then establish laterality','<p><strong>Primary:</strong> inappropriate high aldosterone with suppressed renin. <strong>Secondary aldosterone excess</strong> (e.g., renal artery stenosis): renin and aldosterone both high.</p><p><strong>Clarification:</strong> positive screening may require aldosterone-suppression testing, but not every strong biochemical presentation needs it. CT/MRI describes adrenal anatomy; <strong>adrenal vein sampling</strong> often determines unilateral versus bilateral secretion before surgery. An image alone may not prove the functioning side. '+aldo+'</p>',['pa-high-aldo-low-renin','secondary-aldo-high-renin','pa-confirm-context','pa-imaging-anatomy','avs-functional-laterality'],[
        q('Which hormone pattern distinguishes primary from secondary aldosterone excess?','Primary: high aldosterone/low renin; secondary: high aldosterone/high renin',['Primary: low aldosterone/high renin; secondary: both low','Both always have low cortisol/high ACTH','Both must have the same renin pattern'],'Autonomous secretion suppresses renin; renin-driven secretion does not.'),
        q('What can adrenal vein sampling establish before PA surgery?','Whether aldosterone secretion is predominantly unilateral or bilateral',['Whether cortisol rises after cosyntropin','Whether a lung tumor secretes ACTH','Whether thyroid antibodies are positive'],'Functional laterality guides surgery versus medical care.')
      ],[q('A patient has a positive PA evaluation and a small unilateral nodule on CT. Does the image alone always prove unilateral aldosterone secretion?','No; functional subtype assessment, often adrenal vein sampling, may be needed',['Yes; every nodule produces aldosterone','Yes; the other gland cannot have hyperplasia','No; imaging can never be useful'],'Anatomy and hormone secretion are related but not interchangeable.')]),
      u('Unilateral adenoma versus bilateral hyperplasia','<p><strong>Confirmed unilateral aldosterone source:</strong> unilateral adrenalectomy when suitable; BP and K often improve, though BP cure is not guaranteed.</p><p><strong>Bilateral hyperplasia</strong> or nonsurgical care: mineralocorticoid-receptor antagonism with <strong>spironolactone (Aldactone)</strong> or <strong>eplerenone (Inspra)</strong>. Monitor BP, K and renal function. Removing one gland does little for bilateral secretion.</p>',['pa-unilateral-adrenalectomy','pa-bp-not-guaranteed-cure','pa-bilateral-mra','spironolactone-eplerenone','mra-k-renal-monitor'],[
        q('Which treatment fits confirmed bilateral adrenal hyperplasia causing PA?','Spironolactone or eplerenone-based medical care',['Routine unilateral adrenalectomy as definitive bilateral therapy','Fludrocortisone to increase mineralocorticoid effects','Hydrocortisone stress dosing as the only long-term treatment'],'Receptor antagonism treats excess aldosterone action from both glands.'),
        q('Which treatment fits an appropriate surgical candidate with confirmed unilateral aldosterone production?','Unilateral adrenalectomy',['Bilateral removal for every unilateral adenoma','Fludrocortisone alone','Pituitary resection regardless of ACTH'],'Treat the functioning adrenal side after proper subtype assessment.')
      ],[q('A patient with bilateral PA is started on spironolactone. What follow-up is important?','BP, potassium, and renal function',['Only the size of a pituitary lesion','Only urine ketones once a year','No laboratory follow-up because K was previously low'],'Antagonizing aldosterone can change potassium and kidney-related treatment risks.')])
    ]),
    s('12-androgen-excess','12. Adrenal/androgen excess: findings, evaluation, care','Objective 12 (“adrenal excess”). Part II slides 30–34 address androgen excess; adrenal cortisol/aldosterone excess is covered above.',[
      u('Excess androgens: signs and likely sources','<p>In women, androgens come from ovaries and adrenals; skin/fat can convert weak androgens to more potent forms. In men, testes dominate androgen production.</p><p><strong>PCOS</strong> is the common female androgen-excess cause. Others include androgen-secreting adrenal/ovarian tumors, congenital synthesis disorders, Cushing syndrome and prolactin-related disorders.</p><p>Look for <strong>hirsutism, acne, male-pattern scalp hair loss, menstrual irregularity</strong>, and with marked excess <strong>virilization</strong> such as voice deepening.</p>',['androgen-ovary-adrenal-peripheral','androgen-pcos-common','androgen-tumor-cah-cushing-prolactin','androgen-hirsutism-acne-hair-cycle','androgen-virilization'],[
        q('Which findings suggest androgen excess in a woman?','Hirsutism, acne, scalp hair loss, and irregular cycles',['Salt craving, orthostasis, and new crease pigmentation alone','Only episodic headache/palpitations/sweating','Only low libido with reduced pubic hair'],'The manifestations reflect excess androgen action.'),
        q('Which source distinction matters in female androgen excess?','Both ovarian and adrenal causes are possible',['Every case must come from an adrenal tumor','Ovaries never contribute androgens','Adrenal medulla catecholamines are the only androgens'],'A source-directed evaluation prevents mislabeling all cases as adrenal.')
      ],[q('A woman has rapid progression of hirsutism and voice deepening. Which reasoning is appropriate?','Evaluate marked androgen excess and possible tumor rather than assuming routine PCOS',['Treat the voice change as proof of aldosterone excess','Assume every female androgen abnormality is an adrenal adenoma','Ignore because all androgen changes are cosmetic'],'Severity and tempo influence concern for a secreting lesion.')]),
      u('Evaluate the source; treat a secreting adrenal mass','<p>Lecture laboratory evaluation includes <strong>total testosterone, DHEAS, 17-hydroxyprogesterone, TSH and prolactin</strong>. Testosterone/DHEAS help characterize the androgen pattern; 17-hydroxyprogesterone helps assess a congenital adrenal synthesis disorder.</p><p>Pelvic ultrasound can assess ovarian pathology; adrenal imaging follows suspected adrenal disease. A secreting adrenal tumor is treated by <strong>surgical removal</strong>; nonadrenal causes need their own treatment.</p><p>Associated issues include insulin resistance and cardiometabolic risk, reviewed in objective 15.</p>',['androgen-testosterone-dheas','androgen17ohp-tsh-prolactin','androgen-pelvic-adrenal-imaging','androgen-adrenal-tumor-resect','androgen-nonadrenal-treatment','androgen-associated-metabolic'],[
        q('Which lecture lab panel helps evaluate androgen excess?','Testosterone/DHEAS, 17-hydroxyprogesterone, TSH, and prolactin',['Only aldosterone and renin','Only cosyntropin-stimulated cortisol','Only urine metanephrines'],'These tests assess the androgen pattern and alternative endocrine causes.'),
        q('What is the source-directed treatment for an androgen-secreting adrenal tumor?','Surgical removal with appropriate tumor evaluation',['Fludrocortisone replacement alone','Spironolactone automatically replaces tumor assessment','Pituitary surgery regardless of the proven source'],'Symptom management does not replace treatment of a secreting tumor.')
      ],[q('Androgen testing and imaging identify a secreting adrenal mass in a patient with virilization. Which next care direction fits?','Specialist surgical/tumor evaluation for removal',['Assume PCOS and stop source assessment','Give hydrocortisone solely to increase cortisol further','Monitor only glucose without addressing the mass'],'Management follows the identified source and malignancy concern.')])
    ]),
    s('13-pheochromocytoma','13. Pheochromocytoma: mechanism, location, risk, presentation','Objective 13. Part II slides 38–42, 47–49; metastatic-risk terminology is clarified.',[
      u('Chromaffin tumor and catecholamine excess','<p><strong>Pheochromocytoma</strong> arises from adrenal-medullary chromaffin cells and can secrete epinephrine/norepinephrine.</p><p>Related <strong>extra-adrenal paragangliomas</strong> can occur in the abdomen or thorax, including near the inferior mesenteric artery origin, bladder, or other paraganglionic sites. Adrenal tumors may be bilateral, especially in hereditary disease.</p>',['pheo-chromaffin-medulla','pheo-epi-norepi','paraganglioma-extra-adrenal-sites','pheo-bilateral'],[
        q('What produces hormone excess in a pheochromocytoma?','Catecholamine-secreting chromaffin cells of the adrenal medulla',['Cortisol-producing zona fasciculata cells','Aldosterone-producing glomerulosa cells','Pituitary prolactin-producing cells'],'The medullary origin distinguishes it from cortical tumors.'),
        q('What is the preferred term for a related extra-adrenal chromaffin/paraganglionic tumor?','Paraganglioma',['Cushing disease','Primary aldosteronism','Autoimmune Addison disease'],'Location distinguishes adrenal pheochromocytoma from extra-adrenal paraganglioma.')
      ],[q('A catecholamine-secreting tumor is found near an abdominal autonomic ganglion rather than in the adrenal gland. Which category fits?','Extra-adrenal paraganglioma',['Adrenal cortisol adenoma','Pituitary ACTH adenoma','Aldosterone-producing glomerulosa tumor'],'Related tumors can arise outside the adrenal medulla.')]),
      u('Metastatic potential requires long-term attention','<p>The lecture emphasizes greater malignant risk in extra-adrenal disease and spread to <strong>bone, liver and lymph nodes</strong>.</p><p><strong>Terminology clarification:</strong> apparently localized disease is not a guarantee of permanently benign behavior. Metastatic tumor deposits establish metastatic disease; long-term follow-up remains important even after apparently complete resection. '+ref('https://www.cancer.gov/types/pheochromocytoma/hp/pheochromocytoma-treatment-pdq','NCI: tumor behavior and follow-up')+'</p>',['pheo-extra-adrenal-risk','pheo-bone-liver-nodes','pheo-localized-not-guarantee','pheo-metastatic-deposits'],[
        q('Which statement best captures pheochromocytoma/paraganglioma risk?','Localized disease can recur or metastasize; follow-up is needed',['A benign-looking specimen eliminates all future risk','Only adrenal cortical tumors can metastasize','Normal postoperative BP alone guarantees lifelong cure'],'Initial appearance cannot guarantee permanent harmless behavior.'),
        q('Which sites can contain pheochromocytoma/paraganglioma metastases?','Bone, liver, and lymph nodes',['Only the normal adrenal medulla as proof of metastasis','Only a benign renal cyst','Only thyroid follicles in every patient'],'Metastatic deposits occur beyond the normal primary chromaffin tissue.')
      ],[q('A pheochromocytoma was resected and initially appeared localized. The patient asks whether follow-up can stop. Which explanation fits?','No; recurrence/metastatic risk supports long-term surveillance',['Yes; apparently benign pathology removes every future risk','Yes; normal BP makes hormone follow-up unnecessary','No; recurrence is guaranteed in every patient'],'Surveillance reflects possible delayed recurrence, not a claim that all tumors will spread.')]),
      u('Hereditary associations: MEN2, VHL, NF1','<p>Recognize <strong>MEN2, von Hippel–Lindau and neurofibromatosis type 1</strong> associations. Hereditary risk can mean bilateral/multiple tumors and need for family/genetic evaluation.</p><p><strong>MEN2 (RET)</strong> links pheochromocytoma with medullary thyroid carcinoma; MEN2A can include primary hyperparathyroidism. Contrast <strong>MEN1</strong>: parathyroid, anterior pituitary, and enteropancreatic tumors are its classic pattern.</p>',['pheo-men2-vhl-nf1','pheo-hereditary-family','men2-ret-mtc-parathyroid','men1-contrast'],[
        q('Which syndrome associations should raise pheochromocytoma concern?','MEN2, VHL, and NF1',['Only autoimmune PGA type I','Only diabetic kidney disease','Only iodine-deficiency goiter'],'Family/genetic context changes the level of suspicion.'),
        q('Which tumor association is characteristic of MEN2?','Medullary thyroid carcinoma with pheochromocytoma',['Prolactinoma with gastrinoma as the classic pair','Addison disease with candidiasis','Only an aldosterone-producing adenoma'],'MEN2 differs from MEN1 and autoimmune polyglandular syndromes.')
      ],[q('A patient with medullary thyroid cancer and a RET-associated family syndrome develops hypertensive spells. Which additional tumor should be evaluated?','Pheochromocytoma',['Autoimmune Addison disease as the defining MEN2 tumor','A mandatory prolactinoma as the defining MEN2 tumor','Only a nonfunctioning thyroid cyst'],'The MEN2 association makes catecholamine symptoms particularly significant.')]),
      u('Recognize the episodic catecholamine pattern','<p>Classic spells: <strong>headache, palpitations and sweating</strong> with paroxysmal or labile hypertension. Pallor, anxiety, tremulous-type adrenergic symptoms, orthostasis, fatigue, weight loss, chest/abdominal pain or nausea may accompany them.</p><p>Spells can last minutes to hours and recur; hypertension may also be sustained/resistant. Lack of one classic symptom does not rule it out.</p>',['pheo-headache-palpitations-sweating','pheo-paroxysmal-labile-resistant','pheo-pallor-anxiety-orthostasis','pheo-pain-weight-nausea','pheo-spell-time'],[
        q('Which classic symptom combination suggests catecholamine excess?','Headache, palpitations, and sweating with hypertensive spells',['Weight loss, salt craving, and dark creases with hypotension','Purple striae with proximal weakness only','Weakness with persistent hypokalemic alkalosis only'],'The spell pattern is characteristic of pheochromocytoma.'),
        q('Can pheochromocytoma present with sustained/resistant hypertension rather than only discrete spells?','Yes; BP patterns vary',['No; every patient must be normotensive between identical spells','No; only hypotension is possible','Yes, but catecholamine testing then cannot help'],'Do not require an overly rigid presentation.')
      ],[q('A patient reports repeated episodes of pounding heartbeat, headache, sweating, pallor, and BP spikes lasting 20 minutes. Which endocrine cause fits?','Pheochromocytoma/paraganglioma',['Isolated androgen deficiency','Hyporeninemic hypoaldosteronism','Primary adrenal insufficiency as the classic pattern'],'Evaluate a catecholamine-producing tumor in the appropriate clinical context.')])
    ]),
    s('14-pheo-workup-treatment','14. Pheochromocytoma: diagnosis, treatment, surveillance','Objective 14. Part II slides 43–46; brief biochemical/surveillance clarifications.',[
      u('Biochemical testing before tumor localization','<p>Initial tests: <strong>plasma free metanephrines</strong> or <strong>24-hour urinary fractionated metanephrines</strong>. The lecture favors plasma testing in high-risk genetic/family-history patients.</p><p><strong>Clarification:</strong> metanephrines are the preferred initial analytes; VMA alone is less suitable. Sampling conditions/medications can cause misleading results, so follow up positives. Once biochemistry supports the diagnosis, use <strong>CT/MRI</strong> to localize the lesion. '+ppgl+'</p>',['pheo-plasma-free-metanephrines','pheo-urine-fractionated24h','pheo-high-risk-plasma','pheo-vma-not-preferred','pheo-false-positive-review','pheo-biochem-before-ct-mri'],[
        q('Which tests are preferred initial biochemical tests for suspected pheochromocytoma?','Plasma free or urinary fractionated metanephrines',['Random cortisol or urine ketones','ARR without metanephrine testing','A single VMA measurement as the only preferred test'],'Catecholamine metabolites provide the relevant biochemical evidence.'),
        q('What is the role of CT/MRI after supportive pheochromocytoma biochemistry?','Localize the tumor and assess its extent',['Replace all hormone evidence with any incidental nodule','Measure the ARR directly','Prove every small adrenal mass secretes catecholamines'],'Biochemical diagnosis and anatomic localization answer different questions.')
      ],[q('A patient with a hereditary risk syndrome has suspected catecholamine spells. Which initial test fits the lecture and guidance?','Plasma free metanephrines with appropriate sampling/interpretation',['Random cortisol-to-creatinine ratio','Immediate adrenal biopsy before hormone evaluation','A cosyntropin test as the catecholamine test'],'High-risk patients need suitable biochemical evaluation before localization.')]),
      u('Alpha blockade before beta blockade','<p>Prepare a functioning tumor for surgery with <strong>alpha blockade</strong>, e.g., <strong>doxazosin</strong>. Add beta blockade for rate control <strong>only after adequate alpha blockade</strong> if needed.</p><p>Allow preoperative preparation (lecture: <strong>1–2 weeks</strong>) and appropriate salt/fluid repletion as tolerated. <strong>Avoid unopposed beta blockade</strong>: it can worsen alpha-mediated vasoconstriction and precipitate a hypertensive crisis.</p>',['pheo-alpha-first-doxazosin','pheo-beta-after-alpha','pheo-unopposed-beta-risk','pheo-preop1-2weeks-salt-fluid'],[
        q('What is the correct blockade sequence before pheochromocytoma surgery?','Alpha blockade first, then beta blockade if needed',['Beta blockade first, then consider alpha blockade later','Fludrocortisone first to block catecholamines','No preparation because surgery instantly stops secretion'],'Prevent unopposed alpha-mediated vasoconstriction.'),
        q('Why are salt/fluid measures considered during preoperative preparation?','To correct volume contraction and reduce post-treatment hypotension risk',['To intentionally trigger hypertension before surgery','To replace alpha blockade entirely','To treat cortisol deficiency as the main tumor effect'],'Repletion is individualized to cardiovascular/renal tolerance.')
      ],[q('A patient with confirmed pheochromocytoma has hypertension and tachycardia. Which order is appropriate?','Establish alpha blockade before adding a beta blocker for tachycardia',['Give an isolated beta blocker first','Stop all BP medication until the incision','Use only an ACE inhibitor as guaranteed tumor preparation'],'Rate control must not leave alpha vasoconstriction unopposed.')]),
      u('Surgery and perioperative hemodynamic control','<p><strong>Resection</strong> is the main treatment for a resectable tumor after preparation. Approach depends on size/location/risk; cortex-sparing surgery may be considered in selected hereditary/bilateral cases.</p><p>Tumor manipulation can cause marked BP swings. The lecture names <strong>nicardipine/nitroprusside</strong> for intraoperative control. Unresectable disease needs specialist oncologic and catecholamine-symptom treatment; alpha blockade remains important.</p>',['pheo-resection-after-prep','pheo-surgical-approach-individual','pheo-intraop-nicardipine-nitroprusside','pheo-unresectable-specialist-alpha'],[
        q('What is definitive treatment for an appropriately prepared resectable pheochromocytoma?','Surgical removal',['Lifelong beta blockade alone as a guaranteed cure','Hydrocortisone replacement as tumor eradication','Pituitary radiation for every medullary tumor'],'Surgery removes the source, but requires safe preparation and follow-up.'),
        q('Which lecture drugs can help control intraoperative hemodynamic surges?','Nicardipine or nitroprusside',['Fludrocortisone or DHEA','Metformin or levothyroxine','Cosyntropin or CRH'],'Tumor manipulation may release catecholamines and destabilize BP.')
      ],[q('During prepared tumor resection, manipulation causes a sudden BP surge. What treatment concept fits?','Rapid perioperative vasoactive control under the surgical/anesthesia team',['Assume no surge is possible after oral preparation','Give fludrocortisone to increase volume as the sole response','Stop monitoring once the tumor is exposed'],'Preparation lowers risk but does not remove the need for intraoperative control.')]),
      u('Postoperative hormones, recurrence, and genetic surveillance','<p>Check postoperative metanephrines to assess persistent secretion, then repeat surveillance. The lecture teaches <strong>yearly testing for ten years and lifelong testing with MEN</strong>.</p><p><strong>Clarification:</strong> long-term annual biochemical follow-up is essential; Endocrine Society/NCI guidance supports lifelong follow-up, particularly with hereditary or higher-risk disease. Consider genetic counseling/testing and associated-tumor surveillance. '+ref('https://www.cancer.gov/types/pheochromocytoma/hp/pheochromocytoma-treatment-pdq','NCI: postoperative surveillance')+'</p>',['pheo-postop-metanephrines','pheo-lectureannual10-menlifelong','pheo-longterm-guideline','pheo-genetics-associated-surveillance'],[
        q('What laboratory follow-up assesses persistent/recurrent catecholamine secretion after resection?','Postoperative and serial metanephrines',['Only A1C once at surgery','Only aldosterone-to-renin ratio','Only a stimulated cortisol level'],'A biochemical marker of the original tumor helps detect ongoing or returning secretion.'),
        q('What does the lecture specify for MEN-associated pheochromocytoma surveillance?','Lifelong testing',['No follow-up once postoperative BP is normal','Only one week of observation','Stop at age 50 regardless of results'],'Hereditary syndromes warrant enduring surveillance.')
      ],[q('A patient with MEN2 has normal metanephrines after resection. Which follow-up principle fits?','Continue lifelong biochemical/associated-tumor surveillance',['Stop screening permanently after one normal test','Check only glucose if symptoms recur','Normal BP means hereditary risk has disappeared'],'Normal postoperative results show recovery, not removal of the inherited risk.')])
    ]),
    s('15-female-androgen-review','15. Female androgen excess: etiologies and metabolic consequences','Objective 15. Part II slides 31–32; focused reinforcement of the requested female review.',[
      u('Common PCOS versus uncommon tumor/endocrine causes','<p><strong>PCOS is the most common cause</strong> in reproductive-age women. Rarer sources include androgen-secreting tumors, congenital adrenal disorders, Cushing syndrome and prolactin-related conditions.</p><p>Gradual hirsutism/acne with irregular cycles can fit PCOS; severe/rapid virilization warrants assessment for a tumor or other marked androgen disorder. Adrenal origin must be demonstrated rather than assumed.</p>',['female-pcos-common','female-rare-causes','female-tempo-virilization','female-adrenal-not-assumed'],[
        q('What is the most common cause of androgen excess in reproductive-age women in this lecture?','PCOS',['Adrenal carcinoma in most cases','Pheochromocytoma in most cases','Autoimmune adrenal destruction'],'A common cause should be distinguished from rarer dangerous sources.')
      ],[q('A young woman has gradually progressive acne/hirsutism and irregular cycles, while another has abrupt marked virilization. What distinction matters?','PCOS is common, but the rapid severe presentation warrants investigation for other sources',['Both must have identical benign adrenal tumors','Tempo never affects the evaluation','Both are explained by isolated aldosterone deficiency'],'The cause assessment should reflect both prevalence and presentation.')]),
      u('Associated insulin resistance and cardiovascular risk','<p>Female androgen-excess disorders, especially PCOS, commonly cluster with <strong>insulin resistance, dyslipidemia and elevated BP</strong>.</p><p>Recognize risk for <strong>T2DM and cardiovascular disease</strong>; assess metabolic health rather than treating only hair/acne/cycles. These are associations influenced by the underlying disorder and adiposity, not proof that androgen alone causes every complication.</p>',['female-insulin-resistance','female-lipids-bp','female-diabetes-cv-risk','female-metabolic-assessment'],[
        q('Which metabolic issues should be considered with PCOS-associated androgen excess?','Insulin resistance, dyslipidemia, elevated BP, and diabetes/CV risk',['Only adrenal crisis with obligatory hyponatremia','Only episodic catecholamine excess','Only hypoglycemia without long-term metabolic risks'],'The objective includes systemic consequences, not only skin/cycle findings.')
      ],[q('A patient with PCOS asks whether treatment needs to address anything besides hirsutism. Which follow-up focus fits?','Assess glucose/metabolic risk, lipids, BP, and overall health alongside symptom care',['No metabolic review is relevant','Only annual adrenal MRI can prevent diabetes','Treat every case as a catecholamine tumor'],'The associated metabolic burden deserves recognition.')])
    ]),
    s('16-deficiency-incidental-pseudo','16. Androgen deficiency, incidental adrenal masses, pseudo-Cushing','Objective 16. Part II slides 35–37; Part I slide 81. Brief source-labeled management clarifications.',[
      u('Adrenal androgen deficiency and a selective DHEA trial','<p>Primary adrenal insufficiency can reduce adrenal androgens. Women may report <strong>low libido and reduced well-being</strong>; men often have little clinical effect because testes supply most androgens.</p><p>The lecture lists <strong>DHEA 50 mg/day</strong>, converted peripherally to testosterone. <strong>Clarification:</strong> this is a selective monitored trial in persistently symptomatic women after other replacement is optimized, not routine treatment for all patients. Stop if there is no sustained benefit. '+pai+'</p>',['androgen-deficiency-women-libido','androgen-deficiency-men-minimal','dhea50-peripheral','dhea-selective-trial-monitor'],[
        q('Which symptoms can adrenal androgen deficiency cause in women?','Reduced libido and well-being',['Paroxysmal hypertensive sweating spells','Broad purple striae from cortisol excess','Persistent hypokalemic alkalosis'],'Adrenal androgens contribute to sexual/general well-being.'),
        q('How should the lecture’s DHEA option be interpreted clinically?','A selective monitored trial in suitable persistently symptomatic women',['Mandatory lifelong DHEA for all men and women','A replacement for hydrocortisone during crisis','A guaranteed therapy with no need to assess benefit'],'Optimize essential replacement and reassess whether DHEA helps.')
      ],[q('A woman with well-adjusted Addison replacement still has low libido/energy. Which lecture option may be considered under specialist supervision?','A monitored DHEA trial with benefit reassessment',['Stop hydrocortisone and use only DHEA','Give fludrocortisone solely to raise androgen levels','Assume the symptom proves pheochromocytoma'],'This is selective adjunctive care, not a substitute for essential hormone replacement.')]),
      u('Incidentaloma: incidental discovery does not mean no function','<p>An <strong>adrenal incidentaloma</strong> is found on imaging obtained for another reason. It may be nonfunctioning, mildly cortisol-secreting, or another functional/malignant lesion.</p><p>Evaluate hormone activity and imaging risk: <strong>overnight dexamethasone testing</strong> for cortisol autonomy when appropriate; <strong>ARR</strong> with HTN/unexplained hypokalemia; <strong>metanephrines</strong> when imaging is not typical of a benign adenoma or pheochromocytoma is suspected. ACTH helps establish cortisol autonomy.</p><p><strong>Clarification:</strong> pheochromocytoma testing is not restricted only to patients with hypertension. '+incidental+'</p>',['incidental-definition','incidental-functional-malignant','incidental-dst-acth','incidental-arr-context','incidental-metanephrine-context'],[
        q('What defines an adrenal incidentaloma?','An adrenal mass discovered on imaging performed for another reason',['A mass proven hormonally inactive by its name','A mandatory adrenal carcinoma','A pituitary mass found during ACTH testing'],'The term describes discovery, not a complete diagnosis.'),
        q('Which hormone screen is especially relevant to an incidentaloma with HTN or unexplained low K?','Aldosterone/renin and ARR',['Only DHEA supplementation','Only thyroid ultrasound','Only urine ketones'],'The context raises concern for autonomous aldosterone.')
      ],[q('An incidental adrenal mass is found during imaging for unrelated pain. The patient has no obvious Cushingoid appearance. Should function be assumed normal?','No; assess appropriate hormone activity and imaging features',['Yes; incidental always means nonfunctioning','Yes; symptoms are required before any evaluation','No; every incidentaloma must be malignant'],'Mild hormone excess may lack a dramatic phenotype.')]),
      u('Incidentaloma management uses function and imaging risk','<p>The slide’s <strong>“&gt;5 cm or active → surgery; otherwise monitor”</strong> is simplified. <strong>Clarification:</strong> management depends on hormone effects, imaging appearance, growth, and the patient’s risks/preferences, not size alone.</p><p>A homogeneous lipid-rich lesion (<strong>≤10 HU on noncontrast CT</strong>) supports benignity and may need no further imaging. An indeterminate/suspicious lesion needs specialist evaluation, selected repeat imaging, or surgery; mild cortisol autonomy is individualized. '+incidental+'</p>',['incidental-no-size-only','incidental-hu10-homogeneous','incidental-function-growth-patient','incidental-indeterminate-followup-surgery'],[
        q('Which approach is appropriate for adrenal incidentaloma management?','Assess function, imaging risk/growth, and patient factors rather than applying one size rule',['Resect every lesion solely because it exists','Never reassess a lesion under 5 cm regardless of suspicious features','Assume every hormonally active lesion has the same risk and treatment'],'A single diameter cannot replace the full assessment.'),
        q('Which noncontrast CT pattern supports a benign lipid-rich adrenal lesion?','Homogeneous appearance with ≤10 HU',['Every heterogeneous high-attenuation lesion','Any lesion solely because it is under 5 cm','Any mass with increased metanephrines'],'Imaging characteristics help distinguish benign from indeterminate lesions.')
      ],[q('A small adrenal mass has suspicious heterogeneous imaging and possible hormone activity. Should it be dismissed because it is under 5 cm?','No; arrange appropriate specialist evaluation based on the whole risk picture',['Yes; the slide’s size rule excludes all risk','Yes; small masses never secrete hormones','No; all small masses require identical immediate surgery'],'Both function and imaging can matter independently of size.')]),
      u('Pseudo-Cushing states: treat the underlying condition','<p>Alcohol-use disorder, depression, severe stress and some eating/metabolic disorders can produce functional hypercortisolism or a Cushing-like picture. Exogenous steroids and some drug-related fat changes can also mimic features.</p><p>Review the history, use careful testing, and treat the underlying disorder, then reassess. <strong>Pseudo-Cushing</strong> does not justify adrenal/pituitary surgery without confirming autonomous/endogenous tumor-driven excess.</p>',['pseudo-alcohol-depression-stress','pseudo-mimics-exposure','pseudo-underlying-reassess','pseudo-no-unconfirmed-surgery'],[
        q('What is the management principle for a suspected pseudo-Cushing state?','Treat the underlying condition and reassess the cortisol picture',['Resect both adrenal glands before biochemical confirmation','Assume any obesity proves an ACTH adenoma','Treat every abnormal screening result as definitive localization'],'Functional/nonautonomous changes can improve when the trigger is addressed.')
      ],[q('A patient with heavy alcohol use and depression has Cushing-like features and equivocal testing. What approach fits?','Address the underlying conditions and pursue appropriate reassessment before tumor-directed treatment',['Diagnose adrenal carcinoma from appearance alone','Proceed immediately to pituitary surgery without confirmation','Ignore all symptoms because pseudo-Cushing is always harmless'],'The differential and test context must be resolved before irreversible treatment.')])
    ])
  ];
})();
